package com.orionmini.mobile

import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
import java.net.DatagramPacket
import java.net.DatagramSocket
import java.net.InetAddress
import java.security.KeyPair
import kotlin.concurrent.thread

class LanLinkTest {
    /** Generated by the desktop's lan_link.py; tests/test_lan_link.py checks the same file. */
    private val v = Json.parseToJsonElement(javaClass.classLoader!!.getResource("lan-link-vectors.json")!!.readText()).jsonObject
    private fun s(key: String) = v.getValue(key).jsonPrimitive.content

    private fun fixedPhone(): LanLink.Handshake {
        val pair = KeyPair(LanLink.readPublic(LanLink.unb64(s("phone_public"), 65)), LanLink.privateKey(s("phone_private")))
        return LanLink.Handshake("Pixel", pair, LanLink.unb64(s("phone_nonce"), 32))
    }
    private fun rootLine() = buildJsonObject {
        put("type", "link.root"); put("root_code", s("root_code")); put("ephemeral", s("computer_public")); put("nonce", s("computer_nonce"))
    }.toString()

    @Test fun primitivesMatchTheDesktop() {
        val phoneKey = LanLink.unb64(s("phone_public"), 65); val computerKey = LanLink.unb64(s("computer_public"), 65)
        val phoneNonce = LanLink.unb64(s("phone_nonce"), 32); val computerNonce = LanLink.unb64(s("computer_nonce"), 32)
        assertEquals(s("commit"), LanLink.b64(LanLink.commitment(phoneKey, phoneNonce)))
        val digest = LanLink.transcript(s("root_code"), LanLink.unb64(s("commit"), 32), phoneKey, computerKey, phoneNonce, computerNonce)
        assertEquals(s("transcript"), digest.joinToString("") { "%02x".format(it) })
        assertEquals(s("code"), LanLink.comparisonCode(digest))
        val shared = LanLink.agree(LanLink.privateKey(s("phone_private")), computerKey)
        assertEquals(s("shared"), shared.joinToString("") { "%02x".format(it) })
        assertEquals(s("mac_key"), LanLink.macKey(shared, digest).joinToString("") { "%02x".format(it) })
    }

    @Test fun phoneStepsProduceTheDesktopsCodeAndMacs() {
        val phone = fixedPhone()
        val hello = Json.parseToJsonElement(phone.hello().toString(Charsets.UTF_8)).jsonObject
        assertEquals(v.getValue("hello").jsonObject, hello)
        val reveal = Json.parseToJsonElement(phone.root(rootLine()).toString(Charsets.UTF_8)).jsonObject
        assertEquals(setOf("type", "ephemeral", "nonce"), reveal.keys)
        assertEquals(s("phone_public"), reveal.getValue("ephemeral").jsonPrimitive.content)
        assertEquals(s("code"), phone.code)
        assertEquals(s("root_code"), phone.rootCode)
        val request = Json.parseToJsonElement(phone.request(s("request_code")).toString(Charsets.UTF_8)).jsonObject
        assertEquals(s("request_mac"), request.getValue("mac").jsonPrimitive.content)
        phone.received(buildJsonObject { put("type", "link.received"); put("mac", s("received_mac")) }.toString(), s("request_code"))
        assertTrue(runCatching { phone.received(buildJsonObject { put("type", "link.received"); put("mac", s("request_mac")) }.toString(), s("request_code")) }.isFailure)
    }

    @Test fun refusesMalformedRootsAndInvalidPoints() {
        fun rejects(change: (MutableMap<String, JsonElement>) -> Unit) {
            val value = Json.parseToJsonElement(rootLine()).jsonObject.toMutableMap().also(change)
            assertTrue(runCatching { LanLink.Handshake("Pixel").root(JsonObject(value).toString()) }.isFailure)
        }
        rejects { it["extra"] = JsonPrimitive(1) }
        rejects { it["ephemeral"] = JsonPrimitive(LanLink.b64(byteArrayOf(4) + ByteArray(64))) }
        rejects { it["ephemeral"] = JsonPrimitive(s("computer_public") + "A") }
        rejects { it["nonce"] = JsonPrimitive(LanLink.b64(ByteArray(31))) }
        rejects { it["root_code"] = JsonPrimitive("orion-root-v1:\n") }
        rejects { it["type"] = JsonPrimitive("link.here") }
        assertTrue(runCatching { LanLink.Handshake("Pixel").request("orion-approve-v1:x") }.isFailure)
    }

    @Test fun onlyPrivateIpv4PeersAndShortNames() {
        for (address in listOf("192.168.1.7", "10.1.2.3", "172.16.4.4")) assertTrue(address, LanLink.privateIpv4(address))
        for (address in listOf("8.8.8.8", "127.0.0.1", "169.254.1.1", "192.168.001.7", "localhost", "::1", "192.168.0.0"))
            assertFalse(address, LanLink.privateIpv4(address))
        assertEquals("Pixel 9", LanLink.cleanName("Pixel\u0000 9\n"))
        assertEquals("Phone", LanLink.cleanName("  "))
        assertEquals(40, LanLink.cleanName("x".repeat(80)).length)
        assertTrue(runCatching { LanLink.Session(LanLink.Computer("Desk", "8.8.8.8", 49000), "Pixel") }.isFailure)
    }

    @Test fun discoveryAcceptsOnlyAnswersToItsOwnQuery() {
        DatagramSocket(0, InetAddress.getByName("127.0.0.1")).use { computer ->
            val responder = thread {
                val buffer = ByteArray(512)
                val packet = DatagramPacket(buffer, buffer.size)
                computer.receive(packet)
                val query = Json.parseToJsonElement(String(packet.data, 0, packet.length)).jsonObject
                assertEquals(setOf("type", "version", "nonce"), query.keys)
                fun answer(nonce: String, port: JsonElement = JsonPrimitive(49200)) = buildJsonObject {
                    put("type", "link.here"); put("version", 1); put("nonce", nonce); put("name", "Desk\n"); put("port", port)
                }.toString().toByteArray().let { computer.send(DatagramPacket(it, it.size, packet.socketAddress)) }
                answer("A".repeat(22))
                answer(query.getValue("nonce").jsonPrimitive.content, JsonPrimitive("49200"))
                answer(query.getValue("nonce").jsonPrimitive.content)
            }
            val found = LanLink.discover(1500, computer.localPort, listOf("127.0.0.1"))
            responder.join()
            assertEquals(1, found.size)
            assertEquals("Desk", found[0].name); assertEquals(49200, found[0].port)
        }
    }
}
